import React from 'react';

const Header = ({ onOpenSettings, currentLang }) => {
  return (
    <header className="w-full p-6 flex justify-between items-center bg-[#0D0D0D] border-b border-[#F2F2F2]/10 z-50 font-archivo">
      <div 
        className="text-2xl tracking-tighter text-[#F2F2F2] cursor-pointer hover:opacity-80 transition-opacity"
        onClick={() => window.location.href = '/'}
      >
        RAW<span className="text-raw-cyan">.</span>
      </div>
      
      <div className="flex items-center space-x-6">
        {/* Indicador de Idioma Ativo */}
        <div className="hidden sm:block text-[9px] text-raw-bone/30 uppercase tracking-[0.2em] border border-raw-bone/10 px-2 py-1">
          REGION: {currentLang || 'PT-PT'}
        </div>

        {/* Botão para abrir Settings */}
        <button 
          onClick={onOpenSettings}
          className="group flex items-center space-x-3 focus:outline-none"
        >
          <div className="relative">
            <div className="w-2 h-2 bg-raw-cyan rounded-full group-hover:animate-ping absolute inset-0"></div>
            <div className="w-2 h-2 bg-raw-cyan rounded-full relative"></div>
          </div>
          <span className="text-[10px] text-raw-bone/60 uppercase tracking-[0.3em] font-bold group-hover:text-raw-bone transition-colors">
            Menu
          </span>
        </button>
      </div>
    </header>
  );
};

export default Header;
